import{_ as n,C as r,o as a,c as i,ah as t,E as o}from"./chunks/framework.sPHStHqt.js";const _=JSON.parse('{"title":"Agents & Roles","description":"","frontmatter":{},"headers":[],"relativePath":"settings/agents-and-roles.md","filePath":"settings/agents-and-roles.md","lastUpdated":1789630599000}'),l={name:"settings/agents-and-roles.md"};function g(d,e,h,c,m,u){const s=r("ImagePopup");return a(),i("div",null,[e[0]||(e[0]=t('<h1 id="agents-roles" tabindex="-1">Agents &amp; Roles <a class="header-anchor" href="#agents-roles" aria-label="Permalink to &quot;Agents &amp; Roles&quot;">​</a></h1><p>Everyone who signs in to the super-admin panel alongside you is an <strong>agent</strong>, and what each agent can do is decided by their <strong>role</strong>. Together they let you bring colleagues in to help run the platform without handing everyone the keys.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>How to add an agent and assign their role</li><li>How to build a role from the permission tree</li><li>The rules that stop you locking yourself out</li></ul></div><h2 id="roles-come-first" tabindex="-1">Roles come first <a class="header-anchor" href="#roles-come-first" aria-label="Permalink to &quot;Roles come first&quot;">​</a></h2><p>A role is a named bundle of permissions. Because every agent must be given a role when you create them, it&#39;s easiest to set the roles up first.</p><p>Open <strong>Settings → Roles</strong>.</p>',6)),o(s,{src:"/images/agents-and-roles/roles-grid.png",alt:"Roles list"}),e[1]||(e[1]=t('<p>Each row shows the role&#39;s <strong>Name</strong>, its <strong>Description</strong>, and its <strong>Permission type</strong> — <strong>all</strong> for full access, or <strong>custom</strong> for a hand-picked set.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>A fresh install ships with a single <strong>Administrator</strong> role that has every permission. Leave it as the all-access role and create narrower roles beside it.</p></div><h3 id="creating-a-role" tabindex="-1">Creating a role <a class="header-anchor" href="#creating-a-role" aria-label="Permalink to &quot;Creating a role&quot;">​</a></h3><p>Select <strong>Create Role</strong>.</p>',4)),o(s,{src:"/images/agents-and-roles/role-create.png",alt:"Create Role form with the permission tree"}),e[2]||(e[2]=t('<ul><li><strong>Name</strong> <em>(required)</em> — what the role is called, e.g. <em>Support</em>.</li><li><strong>Description</strong> <em>(required)</em> — a line explaining what it&#39;s for.</li><li><strong>Permission type</strong> <em>(required)</em> — choose <strong>All</strong> to grant everything, or <strong>Custom</strong> to pick.</li></ul><p>Choosing <strong>Custom</strong> reveals the <strong>permission tree</strong>. Tick exactly what this role should be able to do:</p><ul><li><strong>Dashboard</strong> — see the dashboard.</li><li><strong>Tenants</strong> — Create, Edit, Delete tenants.</li><li><strong>Settings → Agents / Roles</strong> — Create, Edit, Delete other agents and roles.</li><li><strong>Account Configuration</strong> — reach the Configuration screen.</li><li><strong>Leads</strong> — Edit, Delete cross-tenant leads.</li><li><strong>Quotes</strong> — Edit, Delete cross-tenant quotes.</li></ul><p>Ticking a parent selects everything under it. Select <strong>Save as Role</strong> when you&#39;re done.</p><h2 id="adding-an-agent" tabindex="-1">Adding an agent <a class="header-anchor" href="#adding-an-agent" aria-label="Permalink to &quot;Adding an agent&quot;">​</a></h2><p>With the roles in place, open <strong>Settings → Agents</strong>.</p>',6)),o(s,{src:"/images/agents-and-roles/agents-grid.png",alt:"Agents list"}),e[3]||(e[3]=t('<p>The grid lists each agent&#39;s <strong>ID</strong>, <strong>First Name</strong>, <strong>Last Name</strong>, <strong>Email</strong> and <strong>Status</strong>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The platform&#39;s original super-admin account isn&#39;t shown in this grid — it&#39;s the built-in owner account and can&#39;t be edited or removed from here. The agents you add appear below it.</p></div><p>Select <strong>Create Agent</strong>.</p>',3)),o(s,{src:"/images/agents-and-roles/agent-create.png",alt:"Create Agent form"}),e[4]||(e[4]=t('<ul><li><strong>First Name</strong> / <strong>Last Name</strong> <em>(required)</em> — the agent&#39;s name.</li><li><strong>Email</strong> <em>(required)</em> — their sign-in address. Must be unique across all agents.</li><li><strong>Password</strong> <em>(required)</em> — at least 6 characters.</li><li><strong>Confirm Password</strong> <em>(required)</em> — must match <strong>Password</strong>.</li><li><strong>Status</strong> — turn on to let them sign in. Left off, the account exists but is blocked.</li><li><strong>Role</strong> <em>(required)</em> — the role that decides what they can do.</li></ul><p>Select <strong>Save as Agent</strong>. They can now sign in at <code>/super/login</code> with the email and password you set, and they&#39;ll see only the areas their role allows.</p><h2 id="editing-and-removing" tabindex="-1">Editing and removing <a class="header-anchor" href="#editing-and-removing" aria-label="Permalink to &quot;Editing and removing&quot;">​</a></h2><p>The pencil icon on either grid re-opens the record. On the <strong>agent</strong> edit form the <strong>Password</strong> fields are optional — leave them blank to keep the current password, or fill them in to reset it.</p><p>The trash icon deletes an agent or role, with two guards on roles:</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><ul><li>A role that&#39;s <strong>assigned to any agent</strong> can&#39;t be deleted — <em>&quot;Role can not be deleted, as this is being used in admin user.&quot;</em> Move those agents to another role first.</li><li>You can&#39;t delete the <strong>last remaining</strong> role, or the role <strong>assigned to you</strong> right now. These rules exist so the platform always has at least one working way in.</li></ul></div><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li>Configure Stripe, trials and locale → <a href="/settings/configuration">Configuration</a></li><li>The screens these roles grant access to → <a href="/super-admin/dashboard">Dashboard</a> · <a href="/super-admin/tenant-management">Tenant Management</a></li></ul>',8))])}const f=n(l,[["render",g]]);export{_ as __pageData,f as default};
